export function sameValue(a, b) {
  if (Number.isNaN(a) && Number.isNaN(b)) return true;
  if (a === 0 || b === 0) {
    return 1 / a === 1 / b;
  }
  return a === b;
}

export function defaultTo(value, fallback) {
  if (
    value === undefined ||
    value === null ||
    Number.isNaN(value)
  ) {
    return fallback;
  }
  return value;
}

